var doc = app.activeDocument;
var tf = doc.textFrames[0];
tf.contents = "SUMMER SALE";
tf.textRange.characterAttributes.size = 96;
if (tf.kind == TextType.AREATEXT) { tf.columnCount = 2; tf.columnGutter = 18; }
var outlines = tf.createOutline(); // tf is gone, outlines is a GroupItem

var doc = app.activeDocument;
var r = doc.artboards[0].artboardRect;          // [left, top, right, bottom]
var v = doc.activeView;
v.centerPoint = [(r[0] + r[2]) / 2, (r[1] + r[3]) / 2];
v.zoom = 1;                                     // 100 %
app.redraw();

if (app.documents.length == 0) throw new Error("no document open");
app.userInteractionLevel = UserInteractionLevel.DONTDISPLAYALERTS;
app.coordinateSystem = CoordinateSystem.ARTBOARDCOORDINATESYSTEM;
app.executeMenuCommand("selectall");
app.executeMenuCommand("outline");   // Type > Create Outlines
app.redraw();
app.userInteractionLevel = UserInteractionLevel.DISPLAYALERTS;

var doc = app.activeDocument;
var i = doc.artboards.getActiveArtboardIndex();
doc.selectObjectsOnActiveArtboard();
doc.fitArtboardToSelectedArt(i);
var o = new ExportOptionsPNG24(); o.artBoardClipping = true; o.antiAliasing = true;
doc.exportFile(new File("E:/out/logo.png"), ExportType.PNG24, o);
doc.close(SaveOptions.DONOTSAVECHANGES);

var tf = app.activeDocument.textFrames[0];
var ca = tf.textRange.characterAttributes;
ca.textFont = app.textFonts.getByName("Montserrat-Bold");
ca.size = 48; ca.autoLeading = false; ca.leading = 52; ca.tracking = 40;
var c = new RGBColor(); c.red = 230; c.green = 30; c.blue = 60;
ca.fillColor = c;
ca.capitalization = FontCapsOption.ALLCAPS;

var doc = app.activeDocument;
var st = doc.characterStyles.add("Price");
st.characterAttributes.size = 36;
st.characterAttributes.tracking = -10;
st.characterAttributes.capitalization = FontCapsOption.ALLCAPS;
st.applyTo(doc.textFrames[0].textRange, true);
